$base = "https://banfwix.wixsite.com/banf1"$results = [ordered]@{}function Test-Url($label, $url, [switch]$isApi) {    try {        if ($isApi) {            $r = Invoke-RestMethod $url -TimeoutSec 25            return "OK (json)"        } else {            $r = Invoke-WebRequest $url -UseBasicParsing -TimeoutSec 25            return "$([int]$r.StatusCode) ($($r.Content.Length) bytes)"        }    } catch {        $msg = $_.Exception.Message        if ($msg.Length -gt 80) { $msg = $msg.Substring(0,80) }        return "FAIL: $msg"    }}# === 1. CORE LANDING ===$results['[1] landing_page'] = Test-Url "Landing" "$base"$r2 = $nulltry { $r2 = Invoke-RestMethod "$base/_functions/landing_data" -TimeoutSec 25 } catch {}if ($r2 -and $r2.success) {    $d = $r2.data    $results['[1] landing_data_api'] = "OK - plans:$($d.membershipPlans.Count) ec:$($d.ecMembers.Count) stats:$($d.stats.Count) sponsors:$($d.sponsorshipTiers.Count) budget:$(if($d.budget){'yes'}else{'no'})"    # Check plan names    $planNames = $d.membershipPlans | ForEach-Object { $_.name }    $results['[1] plan_names'] = $planNames -join " | "    # Check EB pricing    $eb = $d.membershipPlans | Where-Object { $_.name -like "*Early Bird*" } | Select-Object -First 1    if ($eb -and $eb.priceTable) {        $results['[1] eb_price_table'] = "Family:$($eb.priceTable.family) Couple:$($eb.priceTable.couple) Ind:$($eb.priceTable.individual) Stu:$($eb.priceTable.student)"    }} else {    $results['[1] landing_data_api'] = "FAIL or no data"}# === 2. MEMBER PORTAL ===$results['[2] member_portal_html'] = Test-Url "Member Portal" "$base/_functions/member_portal"$results['[2] member_data_api'] = Test-Url "Member Data" "$base/_functions/member_data" -isApi# === 3. ADMIN PORTAL ===$results['[3] admin_portal_html'] = Test-Url "Admin Portal" "$base/_functions/admin_portal"$results['[3] admin_data_api'] = Test-Url "Admin Data" "$base/_functions/admin_data" -isApi# === 4. CRM ===$results['[4] crm_dashboard'] = Test-Url "CRM Dashboard" "$base/_functions/crm_admin"$results['[4] crm_stats'] = Test-Url "CRM Stats" "$base/_functions/crm_stats" -isApi# === 5. CHATBOT ===$chatTests = @(    @{ q = "What events does BANF organize?"; label = "events_query" },    @{ q = "How do I become a member?"; label = "membership_query" },    @{ q = "What are the membership fees for 2026?"; label = "fees_query" },    @{ q = "When is Durga Puja 2026?"; label = "puja_query" },    @{ q = "Who is the president of BANF?"; label = "president_query" })foreach ($ct in $chatTests) {    try {        $body = @{ message = $ct.q; sessionId = "test-$(Get-Random)" } | ConvertTo-Json        $r = Invoke-RestMethod "$base/_functions/agent_chat" -Method POST -Body $body -ContentType "application/json" -TimeoutSec 25        $reply = if ($r.reply) { $r.reply.Substring(0, [Math]::Min(100, $r.reply.Length)) + "..." } else { "no reply field" }        $results["[5] chat_$($ct.label)"] = "OK: $reply"    } catch {        $msg = $_.Exception.Message; if ($msg.Length -gt 80) { $msg = $msg.Substring(0,80) }        $results["[5] chat_$($ct.label)"] = "FAIL: $msg"    }}# === 6. RADIO ===$results['[6] radio_page'] = Test-Url "Radio" "$base/_functions/radio_schedule" -isApi# === 7. ANNOUNCEMENTS / WHATSAPP ===$results['[7] announcements'] = Test-Url "Announcements" "$base/_functions/announcements" -isApi# === 8. EVENTS ===$results['[8] events_api'] = Test-Url "Events API" "$base/_functions/events_list" -isApi# === 9. LOCAL PORTAL HTML FILES ===$portals = @('member-portal.html','admin-portal.html','crm-admin.html','unified-ecosystem-dashboard.html')foreach ($p in $portals) {    $path = "banf1-wix/src/public/$p"    if (Test-Path $path) {        $sz = (Get-Item $path).Length        $results["[9] local_$p"] = "exists ($sz bytes)"    } else {        $results["[9] local_$p"] = "MISSING"    }}Write-Host ""Write-Host "=========================================="Write-Host "  BANF PORTAL COMPREHENSIVE TEST RESULTS"Write-Host "=========================================="$results.GetEnumerator() | ForEach-Object {    $status = if ($_.Value -like "OK*" -or $_.Value -like "200*" -or $_.Value -like "exists*") { "[PASS]" } else { "[FAIL]" }    Write-Host "$status $($_.Key): $($_.Value)"}Write-Host "=========================================="Write-Host "Total tests: $($results.Count)"$passed = ($results.Values | Where-Object { $_ -like "OK*" -or $_ -like "200*" -or $_ -like "exists*" }).CountWrite-Host "Passed: $passed / $($results.Count)"